import statistics

def ler_csv(caminho):
    with open(caminho, encoding="utf-8") as arquivo:
        cabecalho = arquivo.readline().strip().split(",")
        registros = []
        for linha in arquivo:
            valores = linha.strip().split(",")
            registro = {}
            for i, coluna in enumerate(cabecalho):
                registro[coluna] = valores[i].strip()
            registros.append(registro)
    return registros


def remover_duplicatas(registros, chave="ID"):
    vistos = set()
    unicos = []
    for registro in registros:
        if registro[chave] not in vistos:
            vistos.add(registro[chave])
            unicos.append(registro)
    return unicos


def para_numero(texto):
    try:
        return float(texto.replace(",", "."))
    except ValueError:
        return None


def limpar(registros):
    for registro in registros:
        registro["Idade"] = para_numero(registro["Idade"])
        registro["Salario"] = para_numero(registro["Salario"])
        registro["Cidade"] = registro["Cidade"].lower()
        registro["Status"] = registro["Status"].capitalize()


def imputar_mediana(registros, campo):
    validos = [r[campo] for r in registros if r[campo] is not None]
    mediana = statistics.median(validos)
    for registro in registros:
        if registro[campo] is None:
            registro[campo] = mediana
    return mediana


def contar(registros, campo):
    contagem = {}
    for registro in registros:
        valor = registro[campo]
        contagem[valor] = contagem.get(valor, 0) + 1
    return contagem


def media_por_grupo(registros, grupo, campo):
    grupos = {}
    for registro in registros:
        grupos.setdefault(registro[grupo], []).append(registro[campo])
    return {chave: statistics.mean(valores) for chave, valores in grupos.items()}


def exportar_csv(registros, caminho):
    cabecalho = list(registros[0].keys())
    with open(caminho, "w", encoding="utf-8") as arquivo:
        arquivo.write(",".join(cabecalho) + "\n")
        for registro in registros:
            linha = [str(registro[coluna]) for coluna in cabecalho]
            arquivo.write(",".join(linha) + "\n")


